1	/* Clock helpers for the Now page.
2	 *
3	 * The whole page is scoped to "the next few hours", so what "now" is matters
4	 * more here than anywhere else. Once the app switches off its testing pre-set
5	 * and onto the device's real clock (a confirmed in-UK location does that), that
6	 * clock has to keep moving — these are the two bits of the ticker that are pure
7	 * enough to test on their own. Everything else about the tick is DOM work and
8	 * lives in app.js.
9	 */
10	
11	/* Milliseconds from `date` to the very next turn of the minute.
12	 *
13	 * The ticker re-arms with this rather than a flat 60 000 ms so it fires ON the
14	 * minute instead of drifting a little later with every hop — the displayed
15	 * clock changes when the real one does. Exactly on the minute returns a whole
16	 * minute (the next boundary), never 0, so a timer can't spin. */
17	export function msToNextMinute(date) {
18	  const elapsed = date.getSeconds() * 1000 + date.getMilliseconds();
19	  return 60000 - elapsed;
20	}
21	
22	/* Short name of a time zone at a given moment — "BST" / "GMT" for the UK. The
23	 * label beside the clock; `timeZone` defaults to the device's own zone.
24	 *
