import { chromium } from "playwright-core";

const zones = ["Europe/London", "America/Los_Angeles", "Asia/Tokyo"];
const browser = await chromium.launch({ executablePath: "/opt/pw-browsers/chromium/chrome-linux/chrome" });

for (const timezoneId of zones) {
  const ctx = await browser.newContext({ timezoneId, viewport: { width: 420, height: 900 } });
  const page = await ctx.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  await page.goto("http://localhost:8877/index.html", { waitUntil: "networkidle" });
  await page.waitForTimeout(1500);
  const info = await page.evaluate(() => {
    const cards = [...document.querySelectorAll(".card")].slice(0, 4).map((c) => {
      const t = c.querySelector(".card-title, h3, .title");
      const time = c.querySelector(".card-time, .time, .meta");
      return `${(t?.textContent || "").trim().slice(0, 34)} | ${(time?.textContent || "").trim().slice(0, 40)}`;
    });
    return { header: document.body.innerText.slice(0, 220).replace(/\n+/g, " / "), cards };
  });
  console.log(`\n=== ${timezoneId} ===`);
  console.log("header:", info.header);
  info.cards.forEach((c) => console.log("  card:", c));
  if (errors.length) console.log("  PAGE ERRORS:", errors.slice(0, 3));
  await page.screenshot({ path: `/tmp/claude-0/-home-user-EdFringeNow/bd18c10a-cbe8-5b8f-82da-80728e0df4e5/scratchpad/now-${timezoneId.replace(/\//g, "-")}.png` });
  await ctx.close();
}
await browser.close();

