import { chromium } from "playwright-core";

// Leaflet is loaded from unpkg, which this sandbox can't reach. Stub it with a
// chainable no-op proxy so the page boots and the (non-map) list renders.
const LEAFLET_STUB = `
  const chain = new Proxy(function () {}, {
    get: (t, k) => (k === "then" ? undefined : chain),
    apply: () => chain,
    construct: () => chain,
  });
  window.L = chain;
`;

const zones = ["Europe/London", "America/Los_Angeles", "Asia/Tokyo"];
const browser = await chromium.launch({
  executablePath: "/opt/pw-browsers/chromium-1194/chrome-linux/chrome",
});

for (const timezoneId of zones) {
  const ctx = await browser.newContext({ timezoneId, viewport: { width: 430, height: 1000 } });
  await ctx.route("**unpkg.com/**", (route) =>
    route.fulfill({
      status: 200,
      contentType: route.request().url().endsWith(".css") ? "text/css" : "application/javascript",
      body: route.request().url().endsWith(".css") ? "" : LEAFLET_STUB,
    }));
  const page = await ctx.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  await page.goto("http://localhost:8877/index.html", { waitUntil: "networkidle" });
  await page.waitForTimeout(1200);

  const info = await page.evaluate(() => {
    const txt = (el) => (el?.textContent || "").replace(/\s+/g, " ").trim();
    const list = document.querySelector("#showList, .show-list, main");
    const rows = [...(list?.querySelectorAll("li, .card, article") || [])]
      .slice(0, 5).map((n) => txt(n).slice(0, 90));
    return {
      clock: txt(document.querySelector("#nowTime, .now-time, header")).slice(0, 120),
      heading: txt(document.querySelector("h2")),
      rows,
    };
  });
  console.log(`\n=== device zone: ${timezoneId} ===`);
  console.log("header :", info.clock);
  console.log("heading:", info.heading);
  info.rows.forEach((r) => console.log("   •", r));
  if (errors.length) console.log("  PAGE ERRORS:", errors.slice(0, 3));
  await page.screenshot({
    path: `/tmp/claude-0/-home-user-EdFringeNow/bd18c10a-cbe8-5b8f-82da-80728e0df4e5/scratchpad/now-${timezoneId.replace(/\//g, "-")}.png`,
    fullPage: false,
  });
  await ctx.close();
}
await browser.close();

